async function api(path,data,method=data===undefined?'GET':'POST'){
  const res=await fetch('/api'+path,{method,headers:data===undefined?{}:{'content-type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});
  const out=await res.json();if(!res.ok){if(res.status===401 && user){user=null;clearInterval(timer);renderLogin();}throw new Error(out.error || 'ไม่สามารถดำเนินการได้');}return out;
}
function badge(status){return `<span class="badge ${esc(status)}">${esc(labels[status] || status)}</span>`;}
function fmtTime(t){return t?new Date(t).toLocaleString('th-TH',{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Bangkok'}):'—';}
