function shell(body,title){
  document.body.classList.remove('cert-mode');document.title=(config.company||'SuperX Academy')+' | ประเมินทักษะพนักงาน';
  app.innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="brand-sub">EMPLOYEE EXPERIENCE</div><nav class="nav">${(user.role==='admin'?navItems:user.role==='hr'?[['hr','results','ผลสอบพนักงาน']]:[['my-exams','document','ข้อสอบของฉัน']]).map(([id,glyph,label])=>`<button data-nav="${id}" class="${view===id?'active':''}"><span class="nav-icon">${icon(glyph)}</span>${label}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="row"><span class="avatar">${icon('user')}</span><div><div class="small">${esc(user.name)}</div><div class="small muted">${user.role==='admin'?'Assessment Manager':user.role==='hr'?'ฝ่าย HR':esc(depts[user.department])}</div></div></div><button class="logout">ออกจากระบบ</button></div></aside><div class="content"><header class="topbar"><span>SuperX Academy <span class="breadcrumb-divider">/</span><strong>${esc(title)}</strong></span><div class="row"><span>${new Date().toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Bangkok'})}</span><button class="secondary small logout">ออกจากระบบ</button></div></header><main class="workspace">${body}</main></div></div>`;
  $$('[data-nav]').forEach(b=>b.onclick=async()=>{if(dirty && !confirm('มีคำตอบที่ยังบันทึกไม่สำเร็จ ต้องการออกจากหน้านี้หรือไม่?'))return;view=b.dataset.nav;location.hash='';await render();});
  $$('.logout').forEach(b=>b.onclick=async()=>{if(dirty && !confirm('มีคำตอบที่ยังบันทึกไม่สำเร็จ ต้องการออกจากระบบหรือไม่?'))return;try{await api('/logout',{});user=null;dirty=false;clearInterval(timer);location.hash='';renderLogin();}catch(e){toast(e.message);}});
  syncWatermark();
}
function head(title,sub,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
const exportButton=()=>`<a class="report-link" href="/api/admin/export">ดาวน์โหลดผลสอบ</a>`;
function stats(){const a=overview.attempts;return `<div class="stats"><div class="card stat"><span class="stat-label">พนักงานในระบบ</span><span class="value">${overview.employees.filter(e=>e.active).length}</span><span class="foot">จาก 3 ฝ่าย</span></div><div class="card stat accent"><span class="stat-label">ผลสอบผ่าน</span><span class="value">${a.filter(a=>a.status==='passed').length}</span><span class="foot">คะแนนตั้งแต่ 95% ขึ้นไป</span></div><div class="card stat amber"><span class="stat-label">รอประเมินข้อเขียน</span><span class="value">${a.filter(a=>a.status==='pending_review').length}</span><span class="foot">รอการยืนยันจากผู้ประเมิน</span></div><div class="card stat"><span class="stat-label">ผลสอบไม่ผ่าน</span><span class="value">${a.filter(a=>a.status==='failed').length}</span><span class="foot">สอบซ่อมได้ 1 ครั้ง</span></div></div>`;}
function resultsTable(list){return `<div class="table-wrap"><table><thead><tr><th>พนักงาน</th><th>ฝ่าย</th><th>ครั้งที่</th><th>คะแนน</th><th>สถานะ</th><th>ส่งข้อสอบ</th><th></th></tr></thead><tbody>${list.length?list.map(a=>`<tr><td><strong>${esc(a.name)}</strong><div class="sub">${esc(a.employee_id)}</div></td><td>${esc(depts[a.department])}</td><td>${a.attempt_no===2?'สอบซ่อม':'ครั้งแรก'}</td><td>${a.result?`${a.result.earned}/${a.result.total} <span class="muted">${a.status==='pending_review'?'(ยังไม่ครบ)':`(${a.result.percent}%)`}</span>`:'—'}</td><td>${badge(a.status)}</td><td>${fmtTime(a.submitted_at)}</td><td><div class="row"><button class="secondary small" data-review="${esc(a.id)}">${a.status==='pending_review'?'ตรวจคำตอบ':'ดูรายละเอียด'}</button>${a.status==='passed'?`<button class="secondary small" data-cert="${esc(a.id)}">ใบประกาศ</button>`:''}</div></td></tr>`).join(''):'<tr><td colspan="7" class="table-empty">ยังไม่มีผลสอบ เมื่อพนักงานส่งคำตอบจะแสดงที่นี่</td></tr>'}</tbody></table></div>`;}
function bindReviews(){$$('[data-review]').forEach(b=>b.onclick=()=>{location.hash='review/'+b.dataset.review;});bindCerts();}
function renderOverview(){
  const a=overview.attempts;
  shell(head('ภาพรวมการประเมิน','ติดตามทักษะและความพร้อมของทีมในที่เดียว',exportButton())+`<section class="hero"><div><div class="eyebrow muted">ASSESSMENT STANDARD</div><h2 class="spacer">พร้อมไปด้วยกัน ในมาตรฐาน SuperX</h2><p>มองเห็นศักยภาพของทีม และเติมทักษะให้พร้อมสำหรับการทำงานจริง</p></div><div class="policy"><div><strong>95%</strong><span>คะแนนขั้นต่ำที่ผ่าน</span></div><div><strong>1 ครั้ง</strong><span>สอบซ่อมเมื่อไม่ผ่าน</span></div></div></section>`+stats()+`<div class="grid two"><section class="card"><div class="panel-title"><h2>ความคืบหน้าแต่ละฝ่าย</h2><span class="small muted">ผลสอบที่ยืนยันแล้ว</span></div>${Object.entries(depts).map(([id,title])=>{const all=a.filter(x=>x.department===id && ['passed','failed'].includes(x.status)),passed=all.filter(x=>x.status==='passed').length;return `<div class="department"><div class="row between"><strong class="small">${title}</strong><span class="small muted">${passed} / ${all.length} ผลสอบผ่าน</span></div><progress max="${all.length||1}" value="${passed}" class="dept-progress" aria-label="${title}"></progress><div class="legend">${overview.employees.filter(e=>e.department===id&&e.active).length} พนักงาน · ${a.filter(x=>x.department===id&&x.status==='pending_review').length} รอประเมิน</div></div>`;}).join('')}</section><section class="card"><div class="panel-title"><h2>ขั้นตอนถัดไป</h2><span class="badge">สำหรับผู้ประเมิน</span></div><div class="stack"><div class="notice">${a.some(x=>x.status==='pending_review')?`มีข้อสอบรอประเมิน ${a.filter(x=>x.status==='pending_review').length} รายการ ตรวจคะแนนข้อเขียนเพื่อสรุปผลให้พนักงาน`:'เริ่มจากเพิ่มพนักงาน จัดเตรียมข้อสอบ แล้วเปิดให้ฝ่ายที่เกี่ยวข้องเข้าสอบ'}</div><div class="integration"><span>ข้อสอบที่เปิดใช้งาน</span><strong>${overview.exams.filter(x=>x.published).length} ชุด</strong></div><div class="integration"><span>ส่งผลไป Lark</span><span>${overview.integrations.lark?'<span class="integration-dot"></span>เชื่อมต่อแล้ว':'<span class="integration-dot off"></span>รอตั้งค่า'}</span></div><button class="secondary" id="next-action">${a.some(x=>x.status==='pending_review')?'ไปตรวจคำตอบ':'จัดการชุดข้อสอบ'}</button></div></section></div><section class="card spacer"><div class="panel-title"><h2>การประเมินล่าสุด</h2><button class="secondary small" id="all-results">ดูผลทั้งหมด</button></div>${resultsTable(a.slice(0,6))}</section>`,'ภาพรวม');
  bindReviews();$('#all-results').onclick=()=>{view='results';render();};$('#next-action').onclick=()=>{view=a.some(x=>x.status==='pending_review')?'results':'exams';render();};
}
function renderResults(){shell(head('ผลสอบและตรวจคำตอบ','ตรวจคำตอบ ยืนยันคะแนน และติดตามสิทธิ์สอบซ่อม',exportButton())+stats()+`<section class="card"><div class="row filters"><input id="search" placeholder="ค้นหาชื่อหรือรหัสพนักงาน" aria-label="ค้นหาพนักงาน"><select id="status-filter" aria-label="สถานะ"><option value="">ทุกสถานะ</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><select id="dept-filter" aria-label="ฝ่าย"><option value="">ทุกฝ่าย</option>${Object.entries(depts).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div id="results-table">${resultsTable(overview.attempts)}</div><p class="legend spacer">จำนวนบนหน้านี้เป็นรายครั้งที่สอบ รวมครั้งแรกและสอบซ่อม · แสดงล่าสุดไม่เกิน 1,000 รายการ ส่วนไฟล์ดาวน์โหลดรวมทุกรายการ</p></section>`,'ผลสอบ');const filter=()=>{const term=$('#search').value.toLowerCase(),status=$('#status-filter').value,dept=$('#dept-filter').value;$('#results-table').innerHTML=resultsTable(overview.attempts.filter(a=>(a.name+' '+a.employee_id).toLowerCase().includes(term)&&(!status||a.status===status)&&(!dept||a.department===dept)));bindReviews();};['#search','#status-filter','#dept-filter'].forEach(s=>$(s).oninput=filter);bindReviews();}
function renderEmployees(){shell(head('พนักงาน','จัดการอีเมลที่ได้รับสิทธิ์เข้าสอบผ่านอีเมลหรือ Lark')+`<div class="grid two"><section class="card"><h2>เพิ่มพนักงาน</h2><form id="employee-form"><label><span class="label">รหัสพนักงาน (ใช้อ้างอิงผลสอบ)</span><input name="id" placeholder="SX-001" pattern="[a-zA-Z0-9_-]+" maxlength="80" required></label><label><span class="label">ชื่อ–นามสกุล</span><input name="name" required maxlength="200"></label><label><span class="label">ชื่อ–นามสกุลภาษาอังกฤษ (แสดงบนใบประกาศ)</span><input name="name_en" maxlength="200" placeholder="Somchai Jaidee"></label><label><span class="label">อีเมลบริษัท</span><input name="email" type="email" required maxlength="254" placeholder="name@super-x.tech"></label><label><span class="label">ฝ่าย</span>${deptSelect()}</label><button>เพิ่มและอนุญาตให้เข้าสอบ</button><div class="error" id="employee-error"></div></form></section><section class="card"><h2>อีเมลเดียว ใช้งานได้สองช่องทาง</h2><p class="muted small">พนักงานรับรหัสยืนยันทางอีเมล หรือใช้บัญชี Lark ที่ผู้ดูแลผูก Open ID ให้แล้ว บัญชี Lark ต้องอยู่ในองค์กรที่กำหนด</p><div class="notice">การเปลี่ยนอีเมลหรือบัญชี Lark จะยกเลิกการเข้าสู่ระบบเดิม ผลสอบและจำนวนสิทธิ์สอบยังคงเดิม</div></section></div><section class="card spacer"><h2>รายชื่อพนักงาน</h2><div class="table-wrap"><table><thead><tr><th>รหัส</th><th>ชื่อ</th><th>อีเมล</th><th>ฝ่าย</th><th>สถานะ</th><th></th></tr></thead><tbody>${overview.employees.map(e=>`<tr><td>${esc(e.id)}</td><td>${esc(e.name)}${e.name_en?`<div class="sub">${esc(e.name_en)}</div>`:''}</td><td>${esc(e.email||'ยังไม่ได้ระบุอีเมล')}</td><td>${depts[e.department]}</td><td>${e.active?'ใช้งาน':'ปิดใช้งาน'}</td><td>${e.active?`<div class="row"><button class="secondary small" data-identity="${esc(e.id)}">อีเมล / Lark</button><button class="secondary small" data-profile="${esc(e.id)}">ชื่ออังกฤษ</button><button class="secondary small" data-deactivate="${esc(e.id)}">ปิดสิทธิ์</button></div>`:''}</td></tr>`).join('') || '<tr><td colspan="6" class="table-empty">ยังไม่มีพนักงานในระบบ</td></tr>'}</tbody></table></div></section><section class="card spacer"><h2>บัญชีฝ่าย HR</h2><p class="muted small">ฝ่าย HR เข้าสู่ระบบด้วยอีเมล (รหัสยืนยัน) หรือ Lark เพื่อดูผลผ่าน/ไม่ผ่าน ดาวน์โหลดรายงาน และเปิดใบประกาศ แก้ไขข้อมูลหรือข้อสอบไม่ได้</p><form id="hr-form" class="row filters"><input name="name" placeholder="ชื่อ–นามสกุล" required maxlength="200" aria-label="ชื่อ HR"><input name="email" type="email" placeholder="hr@super-x.tech" required maxlength="254" aria-label="อีเมล HR"><button>เพิ่มบัญชี HR</button></form><div class="error" id="hr-error"></div><div class="table-wrap"><table><thead><tr><th>ชื่อ</th><th>อีเมล</th><th>Lark</th><th>สถานะ</th><th></th></tr></thead><tbody>${(overview.hr_users||[]).map(h=>`<tr><td>${esc(h.name)}</td><td>${esc(h.email)}</td><td>${h.lark_open_id?'ผูกแล้ว':'—'}</td><td>${h.active?'ใช้งาน':'ปิดใช้งาน'}</td><td>${h.active?`<button class="secondary small" data-hr-off="${esc(h.email)}">ปิดสิทธิ์</button>`:''}</td></tr>`).join('')||'<tr><td colspan="5" class="table-empty">ยังไม่มีบัญชี HR</td></tr>'}</tbody></table></div></section>`,'พนักงาน');
$('#hr-form').onsubmit=async e=>{e.preventDefault();const b=$('button',e.target);b.disabled=true;try{await api('/admin/hr',Object.fromEntries(new FormData(e.target)));await render();toast('เพิ่มบัญชี HR แล้ว');}catch(err){$('#hr-error').textContent=err.message;}finally{b.disabled=false;}};
$$('[data-hr-off]').forEach(b=>b.onclick=async()=>{if(!confirm('ปิดสิทธิ์บัญชี HR นี้? ผู้ใช้จะถูกออกจากระบบทันที'))return;try{await api('/admin/hr/'+encodeURIComponent(b.dataset.hrOff)+'/deactivate',{});await render();}catch(e){toast(e.message);}});
$$('[data-profile]').forEach(button=>button.onclick=()=>{const emp=overview.employees.find(e=>e.id===button.dataset.profile);showModal(`<h2>ชื่อภาษาอังกฤษบนใบประกาศ</h2><p>${esc(emp.name)} (${esc(emp.id)})</p><form id="profile-form"><label><span class="label">ชื่อ–นามสกุลภาษาอังกฤษ</span><input name="name_en" value="${esc(emp.name_en||'')}" maxlength="200" placeholder="Somchai Jaidee"></label><p class="small muted">เว้นว่างไว้ ระบบจะใช้ชื่อภาษาไทยบนใบประกาศ การแก้ชื่อไม่ทำให้พนักงานออกจากระบบ</p><div class="error" id="profile-error"></div><button>บันทึกชื่อ</button></form>`);$('#profile-form').onsubmit=async e=>{e.preventDefault();try{await api('/admin/employees/'+emp.id+'/profile',{name_en:new FormData(e.target).get('name_en')});$('#modal').close();await render();toast('บันทึกชื่อภาษาอังกฤษแล้ว');}catch(err){$('#profile-error').textContent=err.message;}};});
$('#employee-form').onsubmit=async e=>{e.preventDefault();const button=$('button',e.target);button.disabled=true;try{await api('/admin/employees',Object.fromEntries(new FormData(e.target)));await render();toast('เพิ่มอีเมลพนักงานที่ได้รับสิทธิ์แล้ว');}catch(err){$('#employee-error').textContent=err.message;}finally{button.disabled=false;}};
$$('[data-identity]').forEach(button=>button.onclick=()=>{const emp=overview.employees.find(e=>e.id===button.dataset.identity);showModal(`<h2>อีเมลและบัญชี Lark พนักงาน</h2><p>${esc(emp.name)} (${esc(emp.id)})</p><form id="identity-form"><label><span class="label">อีเมลบริษัท</span><input type="email" name="email" value="${esc(emp.email||'')}" required maxlength="254"></label><label><span class="label">Lark Open ID (ไม่บังคับ)</span><input name="lark_open_id" value="${esc(emp.lark_open_id||'')}" placeholder="ou_..." maxlength="200"></label><p class="notice warning">ยืนยัน Open ID จากข้อมูลบัญชี Lark ของบริษัทก่อนบันทึก เว้นว่างเพื่อใช้อีเมลอย่างเดียว การเข้าสู่ระบบเดิมจะถูกยกเลิก</p><div class="error" id="identity-error"></div><button>บันทึกอีเมล</button></form>`);$('#identity-form').onsubmit=async e=>{e.preventDefault();try{await api('/admin/employees/'+emp.id+'/identity',{email:new FormData(e.target).get('email'),lark_open_id:new FormData(e.target).get('lark_open_id')});$('#modal').close();await render();toast('เปลี่ยนอีเมลเรียบร้อย');}catch(err){$('#identity-error').textContent=err.message;}};});
$$('[data-deactivate]').forEach(button=>button.onclick=async()=>{if(!confirm('ปิดสิทธิ์เข้าสอบของพนักงานคนนี้? ผลสอบเดิมจะยังอยู่'))return;try{await api('/admin/employees/'+button.dataset.deactivate+'/deactivate',{});await render();}catch(e){toast(e.message);}});
}
function renderExams(){shell(head('ชุดข้อสอบ','แยกข้อสอบตามฝ่าย · เกณฑ์ผ่าน 95% · สอบซ่อมได้ 1 ครั้ง',`<button id="new-exam">สร้างชุดข้อสอบ</button>`)+`<div class="notice warning">ข้อสอบตัวอย่างเป็นร่างเริ่มต้น ควรให้หัวหน้าฝ่ายตรวจเนื้อหาและความเหมาะสมก่อนเปิดใช้จริง ชุดที่เปิดแล้วเก็บประวัติแยกกัน หากเปลี่ยนเนื้อหาให้สร้างชุดใหม่</div><div class="row spacer"><button class="secondary small" id="seed">เพิ่มข้อสอบตัวอย่าง 3 ฝ่าย</button></div><section class="grid three spacer">${overview.exams.map(e=>`<article class="card exam-card"><div class="row between"><div class="icon-tile">${deptIcons[e.department]}</div><span class="badge ${e.published?'passed':''}">${e.published?'เปิดสอบ':'ฉบับร่าง / ปิดสอบ'}</span></div><span class="small muted">${depts[e.department]}</span><h3>${esc(e.title)}</h3><p>${e.questions.length} ข้อ · ${e.duration_minutes} นาที · ผ่าน ${e.pass_percent}%</p><div class="exam-meta">เลือกตอบ ${e.questions.filter(q=>q.type==='mcq').length} ข้อ · ข้อเขียน ${e.questions.filter(q=>q.type==='essay').length} ข้อ</div><button class="secondary" data-exam-detail="${esc(e.id)}">ดูคำถามและเกณฑ์ตรวจ</button><button data-publish="${esc(e.id)}" data-published="${e.published?0:1}">${e.published?'ปิดรับผู้เข้าสอบใหม่':'เปิดให้เข้าสอบ'}</button><button class="secondary small" data-clone="${esc(e.id)}">คัดลอกเป็นชุดใหม่</button></article>`).join('') || '<div class="empty">ยังไม่มีชุดข้อสอบ<br>เริ่มสร้างใหม่หรือเพิ่มข้อสอบตัวอย่างได้เลย</div>'}</section>`,'ชุดข้อสอบ');
$('#seed').onclick=async()=>{try{await api('/admin/seed',{});await render();toast('เพิ่มข้อสอบตัวอย่างเป็นฉบับร่างแล้ว');}catch(e){toast(e.message);}};$('#new-exam').onclick=()=>renderEditor();
$$('[data-publish]').forEach(b=>b.onclick=async()=>{if(!confirm(b.dataset.published==='1'?'ยืนยันว่าได้ตรวจสอบคำถามและเฉลยแล้ว และต้องการเปิดสอบ?':'ปิดรับการสอบใหม่? ผู้ที่เริ่มสอบไปแล้วยังทำต่อได้'))return;try{await api('/admin/exams/'+b.dataset.publish+'/publish',{published:b.dataset.published==='1'});await render();}catch(e){toast(e.message);}});
$$('[data-clone]').forEach(b=>b.onclick=()=>renderEditor(overview.exams.find(e=>e.id===b.dataset.clone)));
$$('[data-exam-detail]').forEach(b=>b.onclick=()=>{const e=overview.exams.find(e=>e.id===b.dataset.examDetail);showModal(`<h2>${esc(e.title)}</h2>${e.questions.map((q,i)=>`<div class="spacer"><strong>${i+1}. ${esc(q.prompt)}</strong><p class="small muted">${q.points} คะแนน · ${esc(q.topic)}</p><p class="review-rubric">${q.type==='mcq'?`เฉลย: ${esc(q.options[q.correct])}<br>${esc(q.explanation)}`:`เกณฑ์ตรวจ: ${esc(q.rubric)}`}</p></div>`).join('')}`);});
}
function renderEditor(source=null){editorQuestions=source?structuredClone(source.questions):[{type:'mcq',prompt:'',topic:'',points:10,options:['','','',''],correct:0,explanation:''}];
shell(head('สร้างชุดข้อสอบ','บันทึกเป็นฉบับร่างและตรวจสอบก่อนเปิดให้พนักงานสอบ')+`<form id="exam-form"><section class="card grid two"><label><span class="label">ชื่อชุดข้อสอบ</span><input name="title" value="${esc(source?source.title+' (ชุดใหม่)':'')}" required maxlength="200"></label><label><span class="label">ฝ่าย</span>${deptSelect()}</label><label><span class="label">เวลาสอบ (นาที)</span><input name="duration_minutes" type="number" min="1" max="180" value="${source?.duration_minutes||30}" required></label><div class="notice">เกณฑ์ผ่าน 95% ขึ้นไป<br>สอบครั้งแรก + สอบซ่อมได้ 1 ครั้ง</div></section><div id="editor-fields"></div><div class="row"><button type="button" class="secondary" id="add-mcq">เพิ่มข้อเลือกตอบ</button><button type="button" class="secondary" id="add-essay">เพิ่มข้อเขียน</button></div><div class="error" id="exam-error"></div><div class="row"><button>บันทึกฉบับร่าง</button><button type="button" class="secondary" id="cancel-editor">กลับหน้าชุดข้อสอบ</button></div></form>`,'ชุดข้อสอบ');
if(source)$('[name=department]').value=source.department;
renderEditorFields();$('#add-mcq').onclick=()=>addQuestion('mcq');$('#add-essay').onclick=()=>addQuestion('essay');$('#cancel-editor').onclick=()=>render();
$('#exam-form').onsubmit=async e=>{e.preventDefault();captureEditor();const b=$('button:not([type])',e.target);if(b)b.disabled=true;try{const f=Object.fromEntries(new FormData(e.target));await api('/admin/exams',{title:f.title,department:f.department,duration_minutes:Number(f.duration_minutes),pass_percent:95,questions:editorQuestions});await render();toast('บันทึกข้อสอบเป็นฉบับร่างแล้ว');}catch(err){$('#exam-error').textContent=err.message;}finally{if(b)b.disabled=false;}};}
function captureEditor(){$$('[data-qindex]').forEach(el=>{const q=editorQuestions[Number(el.dataset.qindex)];$$('[data-field]',el).forEach(input=>{const f=input.dataset.field;q[f]=f==='correct'?Number(input.value)-1:f==='points'?Number(input.value):f==='options'?input.value.split('\n'):f==='keywords'?input.value.split(',').map(s=>s.trim()).filter(Boolean):input.value;});});}
function addQuestion(type){captureEditor();if(editorQuestions.length>=50){toast('เพิ่มได้สูงสุด 50 ข้อ');return;}editorQuestions.push(type==='mcq'?{type,prompt:'',topic:'',points:10,options:['','','',''],correct:0,explanation:''}:{type,prompt:'',topic:'',points:10,rubric:'',keywords:[]});renderEditorFields();}
function renderEditorFields(){$('#editor-fields').innerHTML=editorQuestions.map((q,i)=>`<section class="editor-question stack" data-qindex="${i}"><div class="row between"><h3>ข้อ ${i+1} · ${q.type==='mcq'?'เลือกตอบ':'ข้อเขียน'}</h3><button type="button" class="secondary small" data-remove="${i}">ลบข้อ</button></div><label><span class="label">คำถาม</span><textarea data-field="prompt" required maxlength="3000">${esc(q.prompt)}</textarea></label><div class="grid two"><label><span class="label">หัวข้อความรู้</span><input data-field="topic" value="${esc(q.topic)}" required maxlength="100"></label><label><span class="label">คะแนนเต็ม</span><input type="number" data-field="points" min="0.1" max="100" step="0.1" value="${q.points}" required></label></div>${q.type==='mcq'?`<label><span class="label">ตัวเลือก (หนึ่งตัวเลือกต่อบรรทัด จำนวน 2–6 ตัวเลือก)</span><textarea data-field="options" required>${esc(q.options.join('\n'))}</textarea></label><label><span class="label">ลำดับเฉลย เริ่มจาก 1</span><input type="number" data-field="correct" min="1" max="6" value="${q.correct+1}" required></label><label><span class="label">คำอธิบายเฉลย</span><textarea data-field="explanation" maxlength="2000">${esc(q.explanation)}</textarea></label>`:`<label><span class="label">เกณฑ์ตรวจและแนวทางให้คะแนน</span><textarea data-field="rubric" required maxlength="3000">${esc(q.rubric)}</textarea></label><label><span class="label">คำสำคัญช่วยตรวจ (คั่นด้วยเครื่องหมาย ,)</span><input data-field="keywords" value="${esc(q.keywords.join(', '))}"></label>`}</section>`).join('');
$$('[data-remove]').forEach(b=>b.onclick=()=>{captureEditor();editorQuestions.splice(Number(b.dataset.remove),1);renderEditorFields();});}
function renderIntegrations(){const i=overview.integrations;shell(head('การเชื่อมต่อและประวัติ','ติดตามการส่งผลสอบและการทำงานของผู้ประเมิน')+`<div class="grid two"><section class="card"><h2>ส่งผลสอบผ่าน Lark</h2><div class="notice ${i.lark?'':'warning'}">${i.lark?'ตั้งค่า Webhook แล้ว ระบบจะส่งสถานะรอประเมิน และส่งผลสุดท้ายหลังตรวจครบ':'ยังไม่ได้ตั้งค่า Webhook ผลสอบจะเก็บไว้ในระบบ และรอส่งเมื่อเชื่อมต่อแล้ว'}</div><p class="muted small spacer">แจ้งชื่อพนักงาน ฝ่าย ชุดข้อสอบ คะแนน ผ่าน/ไม่ผ่าน และสิทธิ์สอบซ่อม ไปยังกลุ่มผู้ประเมินที่กำหนด</p><p class="legend">ระบบลองส่งใหม่อัตโนมัติเมื่อส่งไม่สำเร็จ อาจมีข้อความซ้ำหากเครือข่ายขาดระหว่างส่ง ใช้รหัสผลสอบและรุ่นผลเพื่อเทียบรายการ</p></section><section class="card"><h2>ตัวช่วยวิเคราะห์คำตอบ</h2><div class="integration"><span>วิเคราะห์ตามเกณฑ์และคำสำคัญ</span><span class="badge passed">พร้อมใช้งาน</span></div><div class="integration"><span>วิเคราะห์เพิ่มเติมด้วย AI</span><span class="badge ${i.ai?'passed':''}">${i.ai?'เปิดใช้งาน':'ยังไม่เปิดใช้งาน'}</span></div><p class="muted small spacer">ข้อเขียนมีผู้ประเมินตรวจและยืนยันคะแนนทุกครั้ง คำแนะนำและคำสำคัญใช้ช่วยพิจารณาเนื้อหาเท่านั้น</p></section></div><section class="card spacer"><h2>รายการแจ้งผลล่าสุด</h2><div class="table-wrap"><table><thead><tr><th>รหัสผลสอบ</th><th>สถานะ</th><th>จำนวนครั้งที่ส่ง</th><th>รายละเอียด</th><th></th></tr></thead><tbody>${overview.notifications.map(n=>`<tr><td>${esc(n.attempt_id.slice(0,8))}</td><td>${n.state==='sent'?'<span class="badge passed">ส่งสำเร็จ</span>':n.tries>=10?'<span class="badge failed">รอตรวจสอบ</span>':'<span class="badge pending_review">รอส่ง</span>'}</td><td>${n.tries}</td><td>${esc(n.last_error || (n.sent_at?fmtTime(n.sent_at):'จะส่งเมื่อเชื่อมต่อ Lark'))}</td><td>${n.state!=='sent'?`<button class="secondary small" data-retry="${esc(n.id)}">ลองส่งอีกครั้ง</button>`:''}</td></tr>`).join('')||'<tr><td colspan="5" class="table-empty">ยังไม่มีการแจ้งผล</td></tr>'}</tbody></table></div></section><section class="card spacer"><h2>ประวัติการจัดการล่าสุด</h2><div class="table-wrap"><table><thead><tr><th>เวลา</th><th>ผู้ดำเนินการ</th><th>กิจกรรม</th><th>รายการ</th></tr></thead><tbody>${overview.audit.map(a=>`<tr><td>${fmtTime(a.created_at)}</td><td>${esc(a.actor)}</td><td>${esc(({sign_in_email:'เข้าสู่ระบบผ่านอีเมล',sign_in_lark:'เข้าสู่ระบบผ่าน Lark',email_delivery_failed:'ส่งอีเมลยืนยันไม่สำเร็จ',create_employee:'เพิ่มพนักงาน',identity_employee:'เปลี่ยนอีเมลพนักงาน',deactivate_employee:'ปิดสิทธิ์พนักงาน',create_exam:'สร้างข้อสอบ',seed_draft_exams:'เพิ่มข้อสอบตัวอย่าง',publish_exam:'เปิดสอบ',close_exam:'ปิดสอบ',review_attempt:'ยืนยันคะแนน',ai_analysis:'วิเคราะห์ด้วย AI'})[a.action]||a.action)}</td><td>${esc(a.target)}</td></tr>`).join('')||'<tr><td colspan="4" class="table-empty">ยังไม่มีกิจกรรม</td></tr>'}</tbody></table></div></section>`,'การเชื่อมต่อ');
$$('[data-retry]').forEach(b=>b.onclick=async()=>{try{await api('/admin/notifications/retry',{id:b.dataset.retry});toast('เริ่มลองส่งอีกครั้งแล้ว');await render();}catch(e){toast(e.message);}});}
async function renderReview(id){const out=await api('/attempts/'+id);const a=out.attempt,exam=a.exam,employee=overview.employees.find(e=>e.id===a.employee_id);shell(head('ตรวจคำตอบและประเมินผล',`${employee?.name||a.employee_id} · ${depts[exam.department]} · ${a.attempt_no===2?'สอบซ่อม':'สอบครั้งแรก'}`,`<button class="secondary" id="back-results">กลับหน้าผลสอบ</button>`)+`<section class="card"><div class="row between"><div><h2>${esc(exam.title)}</h2><p class="muted small">${esc(a.employee_id)} · ส่งเมื่อ ${fmtTime(a.submitted_at)}</p></div>${badge(a.status)}</div>${a.result?`<div class="row"><span class="result-number">${a.result.earned}</span><span class="muted">/ ${a.result.total} คะแนน ${a.status==='pending_review'?'(ตรวจแล้วบางส่วน)':`· ${a.result.percent}%`}</span></div>`:'<p class="notice">พนักงานกำลังทำข้อสอบ ยังไม่มีผลประเมิน</p>'}<p class="legend">เกณฑ์ผ่าน 95% · ${a.reviewer?`ยืนยันโดย ${esc(a.reviewer)} เมื่อ ${fmtTime(a.reviewed_at)}`:'ข้อเขียนต้องให้ผู้ประเมินยืนยันคะแนน'}</p></section>${a.status!=='in_progress'?`<form id="review-form" class="spacer">${exam.questions.map((q,i)=>{const r=a.result?.questions.find(r=>r.id===q.id),an=a.analysis?.questions?.find(x=>x.id===q.id),answer=a.answers[q.id];return `<section class="card question"><div class="row between"><span class="q-label">ข้อ ${i+1} · ${esc(q.topic)}</span><span class="badge">${q.type==='mcq'?'เลือกตอบ':'ข้อเขียน'} · ${q.points} คะแนน</span></div><h3>${esc(q.prompt)}</h3><div class="review-answer">${esc(q.type==='mcq'?(q.options[answer]||'ไม่ได้ตอบ'):(answer||'ไม่ได้ตอบ'))}</div>${q.type==='mcq'?`<p class="review-rubric spacer">เฉลย: ${esc(q.options[q.correct])}<br>คะแนน ${r?.score??0}/${q.points}<br>${esc(q.explanation)}</p>`:`<p class="review-rubric spacer"><strong>เกณฑ์ตรวจ</strong><br>${esc(q.rubric)}</p>${an?`<div class="notice"><strong>ตัวช่วยตรวจคำสำคัญ</strong><br>พบ: ${esc(an.found.join(', ')||'ไม่พบคำสำคัญ')}<br>ยังไม่พบ: ${esc(an.missing.join(', ')||'—')}<br><span class="small muted">ตรวจเนื้อหาและบริบทประกอบ คำสำคัญไม่ใช้ตัดสินคะแนน</span></div>`:''}${a.status==='pending_review'?`<div class="grid two spacer"><label><span class="label">คะแนนที่ให้ (เต็ม ${q.points})</span><input type="number" name="score-${q.id}" min="0" max="${q.points}" step="0.1" required></label><label><span class="label">เหตุผลและข้อเสนอแนะ</span><textarea name="feedback-${q.id}" required maxlength="2000"></textarea></label></div>`:`<p class="notice spacer">คะแนน ${r?.score}/${q.points}<br>${esc(r?.feedback)}</p>`}`}</section>`;}).join('')}<section class="card"><div class="row between"><h2>วิเคราะห์คำตอบเพิ่มเติม</h2><button type="button" class="secondary small" id="ai-analyze" ${overview.integrations.ai?'':'disabled'}>วิเคราะห์ด้วย AI</button></div><div id="ai-text" class="review-answer">${esc(a.analysis?.ai?.text || 'ผู้ประเมินสามารถอ่านคำตอบเทียบกับเกณฑ์ได้ทันที หากเปิดบริการ AI จะขอคำแนะนำเพิ่มเติมได้')}</div><p class="legend spacer">คำแนะนำอาจคลาดเคลื่อน ผู้ประเมินเป็นผู้ยืนยันคะแนนและผลสอบ</p></section>${a.status==='pending_review'?`<section class="card"><label><span class="label">ชื่อผู้ประเมิน</span><input name="reviewer" value="${esc(user.email)}" readonly></label><div class="notice warning spacer">ตรวจคะแนนทุกข้อให้ครบก่อนยืนยัน ผลที่ยืนยันแล้วจะส่งไป Lark และเปิดสิทธิ์สอบซ่อมให้เมื่อไม่ผ่านในครั้งแรก</div><div class="error spacer" id="review-error"></div><button class="spacer">ยืนยันคะแนนและสรุปผล</button></section>`:''}</form>`:''}`,'ตรวจคำตอบ');
$('#back-results').onclick=()=>{view='results';location.hash='';render();};if($('#ai-analyze'))$('#ai-analyze').onclick=async e=>{e.target.disabled=true;$('#ai-text').textContent='กำลังวิเคราะห์คำตอบ…';try{const o=await api('/admin/attempts/'+id+'/analyze',{});$('#ai-text').textContent=o.analysis.ai.text;}catch(err){$('#ai-text').textContent=err.message;}finally{e.target.disabled=false;}};
if(a.status==='pending_review')$('#review-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),reviews={};for(const q of exam.questions.filter(q=>q.type==='essay'))reviews[q.id]={score:Number(f.get('score-'+q.id)),feedback:f.get('feedback-'+q.id)};const result=exam.questions.reduce((sum,q)=>sum+(q.type==='mcq'?(a.answers[q.id]===q.correct?q.points:0):reviews[q.id].score),0),max=exam.questions.reduce((s,q)=>s+q.points,0);if(!confirm(`ยืนยันคะแนน ${result}/${max} (${(result/max*100).toFixed(2)}%) และผล "${result/max*100>=95?'ผ่าน':'ไม่ผ่าน'}" หรือไม่?`))return;const button=$('button:not([type])',e.target);button.disabled=true;try{await api('/admin/attempts/'+id+'/review',{reviews,reviewer:f.get('reviewer'),revision:a.revision});await render();toast('ยืนยันผลสอบแล้ว');}catch(err){$('#review-error').textContent=err.message;}finally{button.disabled=false;}};
}
async function renderMyExams(){const {exams}=await api('/exams');shell(head(`สวัสดี ${esc(user.name)}`,`${depts[user.department]} · ติดตามข้อสอบและผลประเมินของคุณ`)+`<section class="hero"><div><div class="eyebrow muted">YOUR LEARNING JOURNEY</div><h2 class="spacer">ก้าวต่อไปของคุณ เริ่มต้นที่นี่</h2><p>ประเมินความรู้ ค้นพบจุดแข็ง และพัฒนาทักษะไปกับ SuperX</p></div><div class="policy"><div><strong>95%</strong><span>เกณฑ์ผ่าน</span></div><div><strong>1 ครั้ง</strong><span>สิทธิ์สอบซ่อม</span></div></div></section><section class="grid three">${exams.map(e=>{const last=e.attempts.at(-1),can=!last || (last.status==='failed'&&last.attempt_no===1),progress=last?.status==='in_progress';return `<article class="card exam-card"><div class="icon-tile">${deptIcons[e.department]}</div><span class="small muted">${depts[e.department]}</span><h3>${esc(e.title)}</h3><p>${e.count} ข้อ · ${e.total} คะแนน · ${e.duration_minutes} นาที</p>${last?`${badge(last.status)}${last.result?`<p>คะแนนที่${last.status==='pending_review'?'ตรวจแล้ว':'ได้'}: ${last.result.earned}/${last.result.total}${last.status==='pending_review'?'':` (${last.result.percent}%)`}</p>`:''}<p class="small">ใช้สิทธิ์แล้ว ${last.attempt_no}/2 ครั้ง</p>`:'<span class="badge">ยังไม่ได้เริ่ม</span>'}<div class="exam-meta">${can?last?'สอบครั้งแรกไม่ผ่าน คุณมีสิทธิ์สอบซ่อมอีก 1 ครั้ง':'พร้อมเริ่มการประเมิน':last?.status==='pending_review'?'รอผู้ประเมินตรวจข้อเขียนก่อนสรุปผล':last?.status==='passed'?'ผ่านการประเมินเรียบร้อยแล้ว':progress?'กลับมาทำข้อสอบต่อได้ก่อนหมดเวลา':'ใช้สิทธิ์สอบครบแล้ว กรุณาติดต่อผู้ประเมิน'}</div>${can||progress?`<button data-start="${esc(e.id)}">${progress?'ทำข้อสอบต่อ':last?'เริ่มสอบซ่อม':'เริ่มทำข้อสอบ'}</button>`:''}${last?`<button class="secondary" data-result="${esc(last.id)}">ดู${progress?'การสอบ':'ผลสอบ'}</button>${last.status==='passed'?`<button data-cert="${esc(last.id)}">ใบประกาศ</button>`:''}`:''}</article>`;}).join('')||'<div class="empty">ยังไม่มีข้อสอบเปิดสำหรับฝ่ายของคุณ<br>กรุณาติดต่อผู้ประเมินเพื่อตรวจสอบ</div>'}</section>`,'ข้อสอบของฉัน');
$$('[data-start]').forEach(b=>b.onclick=async()=>{const e=exams.find(e=>e.id===b.dataset.start);if(e.attempts.at(-1)?.status!=='in_progress'&&!confirm(`เริ่ม "${e.title}" ใช้เวลา ${e.duration_minutes} นาที? ระบบจะเริ่มนับเวลาทันที และใช้สิทธิ์สอบ 1 ครั้ง`))return;b.disabled=true;try{const o=await api('/attempts',{exam_id:e.id});location.hash='attempt/'+o.attempt.id;}catch(err){toast(err.message);b.disabled=false;}});$$('[data-result]').forEach(b=>b.onclick=()=>{location.hash='attempt/'+b.dataset.result;});bindCerts();
}
async function renderAttempt(id){attempt=(await api('/attempts/'+id)).attempt;dirty=false;submitting=false;saveQueue=Promise.resolve();if(attempt.status!=='in_progress')return renderResult(attempt);const a=attempt;
shell(head('แบบทดสอบทักษะ',`${esc(a.exam.title)} · ${a.attempt_no===2?'สอบซ่อม (ครั้งสุดท้าย)':'การสอบครั้งแรก'}`)+`<div class="quiz-layout"><div class="quiz-main stack">${a.exam.questions.map((q,i)=>`<section class="card question" id="${q.id}"><div class="row between q-meta"><span class="q-label">ข้อ ${i+1} / ${a.exam.questions.length} · ${esc(q.topic)}</span><span class="badge">${q.type==='mcq'?'เลือกตอบ':'ข้อเขียน'} · ${q.points} คะแนน</span></div><h2>${esc(q.prompt)}</h2>${q.type==='mcq'?`<div class="options">${q.options.map((o,j)=>`<label class="option"><input type="radio" name="${q.id}" value="${j}" ${a.answers[q.id]===j?'checked':''}><span>${esc(o)}</span></label>`).join('')}</div>`:`<label><span class="label">คำตอบของคุณ</span><textarea name="${q.id}" maxlength="6000" rows="6" placeholder="อธิบายแนวคิด ขั้นตอน และเหตุผลประกอบ">${esc(a.answers[q.id])}</textarea></label>`}</section>`).join('')}<div class="notice warning">หากหมดเวลา ระบบจะส่งคำตอบล่าสุดที่บันทึกสำเร็จ กรุณาสังเกตสถานะการบันทึกก่อนออกจากหน้านี้</div></div><aside class="card quiz-side"><span class="small muted">เวลาคงเหลือ</span><div class="timer" id="timer" role="timer">--:--</div><p class="small muted">เกณฑ์ผ่าน 95%</p><div class="q-nav">${a.exam.questions.map((q,i)=>`<a href="#${q.id}" data-q-link="${q.id}" aria-label="ไปข้อ ${i+1}">${i+1}</a>`).join('')}</div><div class="legend" id="answered-count"></div><p id="save-status" class="small muted" aria-live="polite">บันทึกคำตอบล่าสุดแล้ว</p><button id="submit-exam">ส่งคำตอบ</button><div class="notice spacer">สอบซ่อมได้ 1 ครั้ง<br>หลังได้รับผลไม่ผ่าน</div></aside></div>`,'ทำข้อสอบ');
// Question links scroll without changing the application route.
$$('[data-q-link]').forEach(link=>link.onclick=e=>{e.preventDefault();document.getElementById(link.dataset.qLink).scrollIntoView({behavior:'smooth'});});
$$('.quiz-main input,.quiz-main textarea').forEach(input=>input.oninput=()=>{dirty=true;$('#save-status').textContent='มีคำตอบที่กำลังรอบันทึก…';markAnswers();clearTimeout(saveTimer);saveTimer=setTimeout(()=>enqueueSave().catch(()=>{}),700);});
$('#submit-exam').onclick=()=>submitAttempt(false);markAnswers();tick();timer=setInterval(tick,1000);
}
function collectAnswers(){const answers={};for(const q of attempt.exam.questions){if(q.type==='mcq'){const checked=$(`input[name="${q.id}"]:checked`);answers[q.id]=checked?Number(checked.value):null;}else answers[q.id]=$(`textarea[name="${q.id}"]`)?.value||'';}return answers;}
function markAnswers(){const answers=collectAnswers();let count=0;for(const q of attempt.exam.questions){const v=answers[q.id],ok=q.type==='mcq'?v!==null:!!v.trim();if(ok)count++;$(`[data-q-link="${q.id}"]`)?.classList.toggle('answered',ok);}$('#answered-count').textContent=`ตอบแล้ว ${count}/${attempt.exam.questions.length} ข้อ`;}
function enqueueSave(){const answers=collectAnswers(),id=attempt.id;saveQueue=saveQueue.catch(()=>{}).then(async()=>{if(attempt?.id!==id || attempt.status!=='in_progress')return;try{const result=await api('/attempts/'+id+'/save',{answers,revision:attempt.revision});if(result.attempt){attempt=result.attempt;dirty=false;clearInterval(timer);renderResult(attempt);return;}attempt.revision=result.revision;const current=collectAnswers();dirty=JSON.stringify(current)!==JSON.stringify(answers);if($('#save-status'))$('#save-status').textContent=dirty?'กำลังรอบันทึกคำตอบล่าสุด…':'บันทึกคำตอบแล้ว '+new Date(result.saved_at).toLocaleTimeString('th-TH');}catch(e){if($('#save-status'))$('#save-status').textContent='ยังบันทึกไม่สำเร็จ: '+e.message;throw e;}});return saveQueue;}
function tick(){if(!attempt || attempt.status!=='in_progress')return;const left=Math.max(0,Math.ceil((attempt.deadline-Date.now())/1000));if($('#timer'))$('#timer').textContent=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0');if(left===0){clearInterval(timer);submitAttempt(true);}}
async function submitAttempt(expired){if(submitting || attempt.status!=='in_progress')return;if(!expired){const answers=collectAnswers(),missing=attempt.exam.questions.filter(q=>q.type==='mcq'?answers[q.id]===null:!answers[q.id].trim()).length;if(!confirm(`${missing?`ยังไม่ได้ตอบ ${missing} ข้อ `:''}ยืนยันส่งคำตอบ? หลังส่งแล้วจะเปลี่ยนคำตอบไม่ได้`))return;}submitting=true;clearTimeout(saveTimer);const b=$('#submit-exam');if(b)b.disabled=true;try{await saveQueue.catch(()=>{});if(attempt.status!=='in_progress')return;const out=await api('/attempts/'+attempt.id+'/submit',{answers:collectAnswers(),revision:attempt.revision});attempt=out.attempt;dirty=false;clearInterval(timer);renderResult(attempt);}catch(e){toast(e.message);submitting=false;if(b)b.disabled=false;if(expired&&$('#save-status'))$('#save-status').textContent='หมดเวลาแล้ว ระบบจะสรุปจากคำตอบที่บันทึกสำเร็จ กรุณาโหลดหน้าซ้ำเพื่อดูผล';}}
function renderResult(a){clearInterval(timer);dirty=false;const r=a.result;shell(head('ผลการประเมิน',`${esc(a.exam.title)} · ${a.attempt_no===2?'สอบซ่อม':'สอบครั้งแรก'}`)+`<section class="card"><div class="row between"><h2>${esc(user.name)}</h2>${badge(a.status)}</div><div class="row"><span class="result-number">${r?.earned??'—'}</span><span class="muted">/ ${r?.total??'—'} คะแนน</span></div><p>${a.status==='pending_review'?'คะแนนข้อเลือกตอบถูกตรวจแล้ว กำลังรอผู้ประเมินตรวจข้อเขียน คะแนนนี้ยังไม่ใช่ผลสุดท้าย':`คะแนน ${r?.percent}% · เกณฑ์ผ่าน 95%`}</p><div class="notice ${a.status==='failed'?'warning':''}">${a.status==='pending_review'?'เมื่อผู้ประเมินยืนยันแล้ว คุณจะดูผลผ่าน/ไม่ผ่านและข้อเสนอแนะได้ที่หน้านี้':a.status==='passed'?'คุณผ่านการประเมินแล้ว ขอให้นำความรู้ไปใช้ในการทำงานอย่างมั่นใจ':a.attempt_no===1?'คุณสามารถสอบซ่อมได้อีก 1 ครั้ง กลับหน้าข้อสอบเพื่อเริ่มเมื่อพร้อม':'คุณใช้สิทธิ์สอบครบแล้ว กรุณาติดต่อผู้ประเมินเพื่อวางแผนพัฒนาทักษะต่อไป'}</div><p class="legend spacer">ส่งเมื่อ ${fmtTime(a.submitted_at)} · ${a.reviewer?`ยืนยันผลโดย ${esc(a.reviewer)}`:'รอตรวจสอบผล'}</p><div class="row">${a.status==='passed'?`<button data-cert="${esc(a.id)}">ดูใบประกาศ (Certificate)</button>`:''}<button id="back-exams" class="${a.status==='passed'?'secondary':''}">กลับหน้าข้อสอบของฉัน</button><button class="secondary" id="refresh-result">ตรวจสอบผลล่าสุด</button></div></section>${a.status!=='pending_review'?`<section class="card spacer"><h2>ข้อเสนอแนะจากการประเมิน</h2>${r.questions.map((q,i)=>`<div class="department"><div class="row between"><strong class="small">ข้อ ${i+1} · ${esc(q.topic)}</strong><span class="small">${q.score}/${q.max}</span></div><p class="small muted spacer">${esc(q.feedback || 'ตรวจคะแนนตามเกณฑ์ของข้อสอบ')}</p></div>`).join('')}</section>`:''}`,'ผลสอบของฉัน');bindCerts();$('#back-exams').onclick=()=>{location.hash='';render();};$('#refresh-result').onclick=()=>renderAttempt(a.id).catch(e=>toast(e.message));}
async function render(){clearInterval(timer);clearTimeout(saveTimer);try{if(!user)return renderLogin();const certHash=location.hash.slice(1);if(certHash.startsWith('certificate/'))return await renderCertificate(certHash.slice(12));if(user.role==='hr')return await renderHr();if(user.role==='admin'){overview=await api('/admin/overview');const hash=location.hash.slice(1);if(hash.startsWith('review/'))return await renderReview(hash.slice(7));({overview:renderOverview,results:renderResults,employees:renderEmployees,exams:renderExams,integrations:renderIntegrations}[view]||renderOverview)();}else{const hash=location.hash.slice(1);if(hash.startsWith('attempt/'))await renderAttempt(hash.slice(8));else await renderMyExams();}}catch(e){if(user)shell(head('ไม่สามารถเปิดข้อมูลได้','กรุณาลองโหลดหน้าใหม่')+errorBox(e)+`<button class="spacer" id="reload">ลองอีกครั้ง</button>`,'แจ้งเตือน');if($('#reload'))$('#reload').onclick=render;}}
window.addEventListener('hashchange',()=>{if(leaving)return;render();});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
async function boot(){try{config=await api('/config');}catch{}try{user=(await api('/me')).user;}catch{}document.title=config.company+' | ประเมินทักษะพนักงาน';if(user?.role==='employee')view='my-exams';if(user?.role==='hr')view='hr';await render();}
boot();
